//! The embedded payload, generated by `build.rs`.
//!
//! One [`Channel`] per build embedded: stable always, the developer build when it was built
//! complete. Each has `payload` — `(name written to the player, owning component id, bytes)` —
//! the removal packages, kept apart because they land under the same name as the install one, and
//! `missing`, what was absent at compile time, so an incomplete build says so on startup instead
//! of half-working. Files that are the same in both channels are stored once.
//!
//! Which one is installed is the `channel` entry in components.conf (`CINDER_CHANNEL`): the person
//! installing chooses it like any other option, and an Update reads it back from the player.

#![allow(dead_code)]

use crate::catalogue::Comp;

pub struct Channel {
    pub name: &'static str,
    pub payload: &'static [(&'static str, &'static str, &'static [u8])],
    pub uninstall_upg: Option<&'static [u8]>,
    pub uninstall_upg_w1: Option<&'static [u8]>,
    pub missing: &'static [&'static str],
}

include!(concat!(env!("OUT_DIR"), "/payload.rs"));

/// The catalogue entry that picks the channel.
pub const CHANNEL_ID: &str = "channel";

/// The channel called `name`, if this build carries it.
pub fn find(name: &str) -> Option<&'static Channel> {
    CHANNELS.iter().find(|c| c.name == name)
}

/// The channel the installer starts on: the build's default if it carries it, else stable.
pub fn default() -> &'static Channel {
    find(DEFAULT_CHANNEL).unwrap_or(&CHANNELS[0])
}

/// The channel `comps` asks for. An answer this build cannot honour (a developer build that was
/// not embedded) falls back to the default rather than failing: the entry is not offered then.
pub fn chosen(comps: &[Comp]) -> &'static Channel {
    comps
        .iter()
        .find(|c| c.id == CHANNEL_ID)
        .and_then(|c| find(&c.value))
        .unwrap_or_else(default)
}

/// Fit the catalogue to this build: the channel entry starts on the default, and is taken out
/// altogether when only one channel is embedded, because a choice of one is not a choice.
pub fn fit_catalogue(comps: &mut Vec<Comp>) {
    if CHANNELS.len() < 2 {
        comps.retain(|c| c.id != CHANNEL_ID);
        return;
    }
    if let Some(c) = comps.iter_mut().find(|c| c.id == CHANNEL_ID) {
        c.default = default().name.to_string();
        c.value = c.default.clone();
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    /// Stable is always first and always there; every embedded channel has an install package.
    #[test]
    fn stable_is_always_embedded_first() {
        assert_eq!(CHANNELS[0].name, "stable");
        for c in CHANNELS {
            assert!(
                c.payload.iter().any(|(n, _, _)| *n == "cinder-home"),
                "{} has no cinder-home",
                c.name
            );
        }
    }

    /// The choice follows the `channel` entry, and an answer the build cannot honour falls back.
    #[test]
    fn the_channel_entry_picks_the_payload() {
        let mut comps =
            crate::catalogue::parse_catalogue(crate::CATALOGUE.expect("catalogue")).unwrap();
        fit_catalogue(&mut comps);
        let offered = comps.iter().any(|c| c.id == CHANNEL_ID);
        assert_eq!(
            offered,
            CHANNELS.len() > 1,
            "offered only when there is a choice"
        );
        assert_eq!(chosen(&comps).name, default().name);
        if let Some(i) = comps.iter().position(|c| c.id == CHANNEL_ID) {
            comps[i].value = "dev".into();
            assert_eq!(chosen(&comps).name, "dev");
            comps[i].value = "nonsense".into();
            assert_eq!(chosen(&comps).name, default().name);
        }
    }
}
